// Restricted, actor-realizable Gate reachability for Wobbuffet vs Shadow Rider V.
// Compile: g++ -O3 -std=c++17 active-choice.cpp -o active-choice
// Run: ./active-choice [--csv] [--limit N]
// Optional extension: prefix --extended bench or --extended no-bench (public opponent Bench availability).
// After that optional prefix: --context 10 comma flags (support,item,lele,stone,float,latias,sky,gateV,gateRetreat,gateGuzma).
// Flags are effective public permissions, supplied by actor; not a full lock resolver.
// Gate after retreat and after specific legal Guzma target may differ.
// Extended counts insert Guzma,SkyField immediately after Heavy.
// Known-zone draw fallback: --extended bench|no-bench --draw-plan H D P BUDGET GOAL BANKFLAGS
// Draw H,D,P have 17 counts: extended 15 plus Lillie,Iono; Other excludes both.
// BANKFLAGS: Lele,Latias,Float,FSS,Sky,Psychic,Stone,Spent; actual in-play / used state.
// After the draw: --extended bench|no-bench --known-plan H D P BUDGET GOAL BANKFLAGS SUPPORTUSED.
// Fixed inspected search: --known-branch same args plus FIRSTACTION.
// Unknown Prizes after refresh: --posterior-plan UNKNOWN RETURNED DRAW BUDGET GOAL BANKFLAGS lillie|iono.
// Before a K0 refresh: --k0-draw H UNKNOWN BUDGET GOAL BANKFLAGS SAMPLES SEED (MC outer, exact posterior).
// Query: ./active-choice --post H BUDGET GOAL
// Resolve inspected search: ./active-choice --branch H BUDGET GOAL ACTION PRIZES
// H/PRIZES: comma-separated counts V,VMAX,Lele,Latias,Radiant,Arven,Float,FSS,Heavy,Fog,Ball,Psychic,Other.
// H is the seven observed non-Wob cards including V in play/hand; PRIZES used only after legal inspection.
// All source counts from unchanged Lockbridge 60, Wobbuffet fixed in opening.
// No games, opponent-policy assumptions, or win-rate claim.
#include <array>
#include <cassert>
#include <cstdint>
#include <cstdlib>
#include <functional>
#include <iomanip>
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <algorithm>
#include <limits>
#include <tuple>
#include <stdexcept>
#include <random>
#include <cmath>
using namespace std;
using U=uint64_t; using Mask=uint16_t;
enum Card { V,VM,T,L,R,A,F,S,H,X,Y,G,B,P,O,N };
// T=Tapu Lele, L=Latias, R=Radiant Eternatus, A=Arven, F=Float,
// S=Forest Seal Stone, H=Heavy Ball, G=Fog, B=discard search, P=Psychic.
array<int,N> CAP{4,4,1,1,1,1,1,1,1,0,0,4,5,11,24};
bool extended=false,oppBench=false;
// Caller derives these from the current public board and turn. Never infer a lock from an archetype.
// Gate eligibility can differ after a retreat versus a particular legal Guzma target.
struct PublicContext{bool support=true,item=true,lele=true,stone=true,flt=true,latias=true,sky=true,gateV=true,gateRetreat=true,gateGuzma=true;};
PublicContext ctx;
PublicContext parse_context(const string&arg){array<bool,10> a{};size_t pos=0;for(int i=0;i<10;++i){size_t end=arg.find(',',pos);if((i==9)!=(end==string::npos))throw runtime_error("expected 10 public flags: support,item,lele,stone,float,latias,sky,gateV,gateRetreat,gateGuzma");string v=arg.substr(pos,end==string::npos?end:end-pos);if(v!="0"&&v!="1")throw runtime_error("public context flags must be 0 or 1");a[i]=v=="1";pos=end==string::npos?arg.size():end+1;}return {a[0],a[1],a[2],a[3],a[4],a[5],a[6],a[7],a[8],a[9]};}

using Counts=array<int,N>;
U CH[61][61]{};
constexpr int DIRECT=0, ARVEN=1, LELE=2, STONE=3, FOG=4, BALL=5, HEAVY=6, BALL_GUZMA=7, BALL_SKY=8, ACTS=9;
constexpr int VG=0,VF=1,WG=2,WF=3;
// Budget block 0: at most two designated Other discards, FSS allowed.
// 1: same, FSS forbidden. 2: no discard, FSS allowed. 3: neither.
constexpr int BIT(int budget,int goal){return 4*budget+goal;}
constexpr Mask SB(int c){return Mask(1u<<(c-T));}
struct St {
  uint16_t h=0,d=0;
  uint8_t hg=0,hb=0,dg=0,db=0,hp=0,dp=0,pr=0,remain=0,spent=0,stone=0,lele=0,supporter=0,latiasBench=0,sky=0;
  bool held(int c)const { if(c==G)return hg; if(c==B)return hb; if(c==P)return hp; return h&SB(c); }
  bool deck(int c)const { if(c==G)return dg; if(c==B)return db; if(c==P)return dp; return d&SB(c); }
  void remove(int c) { if(c==G){assert(hg);--hg;}else if(c==B){assert(hb);--hb;}else {assert(held(c));h&=~SB(c);} }
  void get(int c){ assert(deck(c)); if(c==G){--dg;++hg;}else if(c==B){--db;++hb;}else if(c==P){dp=0;hp=1;}else {d&=~SB(c);h|=SB(c);} }
  U key()const {U k=h; k=k*512+d; k=k*8+hg; k=k*8+hb; k=k*4+dg; k=k*4+db; k=k*2+hp; k=k*2+dp; k=k*8+pr; k=k*4+remain; k=k*4+spent; k=k*2+stone; k=k*2+lele;k=k*2+supporter;k=k*2+latiasBench;k=k*2+sky;return k;}
};
// T/L/R are the first three singleton bits, matching pr bits.
Mask allowed(const St&s){Mask m=0;for(int b=0;b<4;++b)if((!(b&1)||!s.stone)&&(!(b&2)||!s.spent))m|=Mask(15u<<(4*b));return m;}
bool live_sky(const St&s){return s.sky||(ctx.sky&&s.held(Y));}
bool float_pivot(const St&s){return ctx.gateRetreat&&ctx.flt&&s.held(F);}
bool latias_pivot(const St&s){return ctx.gateRetreat&&ctx.latias&&s.held(L)&&(!s.lele||live_sky(s));}
bool guzma_pivot(const St&s){return ctx.gateGuzma&&ctx.support&&oppBench&&!s.supporter&&s.held(X);}
Mask goals(const St&s){ if(!s.held(R))return 0; bool sky=live_sky(s);bool fits=!(s.latiasBench&&s.lele)||sky;bool w=fits&&(float_pivot(s)||latias_pivot(s)||guzma_pivot(s)); Mask x=(ctx.gateV?1:0)|(ctx.gateV&&s.hp?2:0)|(w?4:0)|(w&&s.hp?8:0);return Mask((x|(x<<4)|(x<<8)|(x<<12))&allowed(s)); }
bool available(const St&s,int a){switch(a){case ARVEN:return ctx.support&&s.held(A)&&!s.supporter;case LELE:return ctx.lele&&s.held(T);case STONE:return ctx.stone&&s.held(S)&&!s.stone;case FOG:return ctx.item&&s.hg;case BALL:return ctx.item&&s.hb&&s.spent<2&&s.remain;case BALL_GUZMA:return ctx.item&&s.hb&&s.spent<2&&s.held(X);case BALL_SKY:return ctx.item&&s.hb&&s.spent<2&&s.held(Y);case HEAVY:return ctx.item&&s.held(H);default:return false;}}
// Each callback receives a state after the named search's result selection.
// First search may fail/decline a restricted search after legally inspecting hidden zone.
// Stone must retrieve a card; 'irrelevant' is abstracted only at first reveal; it cannot pay costs in this model.
template<class Fn> void successors(const St&s,int a,bool first,Fn emit){
 if(!available(s,a))return;
 if(a==ARVEN){St base=s;base.remove(A);base.supporter=1;int its[]={-1,G,B,H};int tls[]={-1,F,S};for(int i:its){if(i>=0&&!base.deck(i))continue;for(int t:tls){if(t>=0&&!base.deck(t))continue;if(i<0&&t<0&&!first)continue;St q=base;if(i>=0)q.get(i);if(t>=0)q.get(t);emit(q);}}}
 else if(a==LELE){St q=s;q.remove(T);q.lele=1;for(int c:{A,X})if(!q.supporter&&q.deck(c)){St r=q;r.get(c);emit(r);}if(first)emit(q);}
 else if(a==STONE){St q=s;q.remove(S);q.stone=1;for(int c:{T,L,R,A,F,H,X,Y,G,B,P})if(q.deck(c)&&!(c==P&&q.hp)){St r=q;r.get(c);emit(r);}if(first)emit(q);}
 else if(a==FOG){St q=s;q.remove(G);for(int c:{T,L,P})if(q.deck(c)&&!(c==P&&q.hp)){St r=q;r.get(c);emit(r);}if(first)emit(q);}
 else if(a==BALL||a==BALL_GUZMA||a==BALL_SKY){int fodder=a==BALL?O:a==BALL_GUZMA?X:Y;St q=s;q.remove(B);if(fodder==O)--q.remain;else q.remove(fodder);++q.spent;for(int c:{T,L,R})if(q.deck(c)){St r=q;r.get(c);emit(r);}if(first)emit(q);}
 else if(a==HEAVY){St q=s;q.remove(H);for(int c:{T,L,R})if(q.pr&SB(c)){St r=q;r.pr&=~SB(c);r.h|=SB(c);emit(r);}if(first)emit(q);}
}
unordered_map<U,Mask> memo;
Mask solve(const St&s){Mask g=goals(s),upper=allowed(s);if(g==upper)return g;U k=s.key();auto it=memo.find(k);if(it!=memo.end())return it->second;
 // If Radiant is neither held, in deck, nor in prizes, no restricted route can produce it.
 if(!s.held(R)&&!s.deck(R)&&!(s.pr&SB(R)))return 0;
 // Lele cannot help after Arven is used/unavailable; no need to expend resources in K1 for empty searches.
 for(int a:{ARVEN,LELE,STONE,FOG,BALL,HEAVY,BALL_GUZMA,BALL_SKY}){if(a==LELE&&(s.supporter||(!s.deck(A)&&!s.deck(X))))continue;successors(s,a,false,[&](const St&q){if(g!=upper)g|=solve(q);});if(g==upper)break;}
 memo.emplace(k,g);return g;}
Mask firstmask(const St&s,int a){if(a==DIRECT)return goals(s);Mask g=0,upper=allowed(s);successors(s,a,true,[&](const St&q){if(g!=upper)g|=solve(q);});return g;}
int prize_key(const Counts&h,const Counts&p){int k=0;for(int c=T;c<=Y;++c)if(CAP[c]-h[c]-p[c])k|=SB(c);int dg=min(2,CAP[G]-h[G]-p[G]),db=min(2,CAP[B]-h[B]-p[B]);k|=dg<<9;k|=db<<11;k|=(CAP[P]-h[P]-p[P]>0)<<13;k|=(CAP[VM]-h[VM]-p[VM]>=2)<<14;return k;}
St make_state(const Counts&h,int k){St s;s.d=k&511;for(int c=T;c<=Y;++c)if(h[c])s.h|=SB(c);s.hg=h[G];s.hb=h[B];s.hp=h[P]>0;s.dg=(k>>9)&3;s.db=(k>>11)&3;s.dp=(k>>13)&1;s.pr=(~(s.h|s.d))&7;s.remain=min(2,h[O]);s.supporter=!ctx.support;return s;}
// Packed hand key; physical-card counts are represented by choose weights.
U handkey(const Counts&h){U k=0;for(int i=0;i<N;++i)k=k*12+h[i];return k;}
U weight(const Counts&h){U w=1;for(int i=0;i<N;++i)w*=CH[CAP[i]][h[i]];return w;}
void enumerate(const Counts&caps,int n,function<void(const Counts&,U)> cb){Counts a{};array<int,N+1> suffix{};for(int i=N-1;i>=0;--i)suffix[i]=suffix[i+1]+caps[i];auto go=[&](auto&&self,int i,int r,U w)->void{if(i==N){if(!r)cb(a,w);return;}for(int x=max(0,r-suffix[i+1]);x<=min(caps[i],r);++x){a[i]=x;self(self,i+1,r-x,w*CH[caps[i]][x]);}};go(go,0,n,1);}
using Vec=array<U,16>; using Table=array<Vec,ACTS>;
Table posttable(const Counts&h,U& worlds,U& grouped){Counts rem;for(int i=0;i<N;++i)rem[i]=CAP[i]-h[i];array<U,32768> bins{};vector<int> keys;U denom=0;enumerate(rem,6,[&](const Counts&p,U w){++worlds;int k=prize_key(h,p);if(!bins[k])keys.push_back(k);bins[k]+=w;denom+=w;});assert(denom==CH[52][6]);grouped+=keys.size();Table a{};for(int k:keys){if(!(k&(1<<14)))continue;St s=make_state(h,k);for(int act=0;act<ACTS;++act){if(act!=DIRECT&&!available(s,act))continue;Mask z=firstmask(s,act);for(int b=0;b<16;++b)if(z&(1u<<b))a[act][b]+=bins[k];}}
 return a;}
Vec post(const Counts&h,U& worlds,U& grouped){Table a=posttable(h,worlds,grouped);Vec best{};for(int b=0;b<16;++b)for(int act=0;act<ACTS;++act)best[b]=max(best[b],a[act][b]);for(int b=0;b<4;++b){if(ctx.gateV){assert(best[BIT(b,WF)]<=best[BIT(b,VF)]);assert(best[BIT(b,WG)]<=best[BIT(b,VG)]);}assert(best[BIT(b,VF)]<=best[BIT(b,VG)]);assert(best[BIT(b,WF)]<=best[BIT(b,WG)]);if(h[F]&&ctx.flt&&ctx.gateRetreat&&ctx.gateV){assert(best[BIT(b,WF)]==best[BIT(b,VF)]);assert(best[BIT(b,WG)]==best[BIT(b,VG)]);}}return best;}
void tests(){St s;s.h=SB(R)|SB(F);s.hp=1;assert(solve(s)==65535);s.h=SB(R)|SB(L);assert(solve(s)==65535);s.lele=1;assert(solve(s)==0x3333);s.lele=0;s.h=SB(R)|SB(S);s.d=SB(F);assert((solve(s)&(1u<<BIT(0,WF)))!=0);assert((solve(s)&(1u<<BIT(1,WF)))==0);
 // One Arven cannot acquire both Float and Stone; with Radiant only available by Stone and no pivot, W fails.
 s={};s.h=SB(A);s.d=SB(F)|SB(S)|SB(R);s.hp=1;assert(solve(s)&(1u<<BIT(0,VF)));assert(!(solve(s)&(1u<<BIT(0,WF))));
 // Arven can acquire Float and Ball together, paying a discard to find Radiant.
 s={};s.h=SB(A);s.d=SB(F)|SB(R);s.db=1;s.hp=1;s.remain=1;assert(solve(s)&(1u<<BIT(1,WF)));assert(!(solve(s)&(1u<<BIT(3,WF))));
 // Lele consumes the fifth slot if Latias is also required; Float route still works.
 s={};s.h=SB(T)|SB(L);s.d=SB(A)|SB(R);s.db=1;s.hp=1;s.remain=1;assert(solve(s)&(1u<<BIT(1,VF)));assert(!(solve(s)&(1u<<BIT(1,WF))));s.d|=SB(F);assert(solve(s)&(1u<<BIT(1,WF)));
 // Prize-only Radiant rescued by one Heavy Ball, and Float allows normal five-Bench Gate.
 s={};s.h=SB(H)|SB(F);s.pr=SB(R);s.hp=1;assert(solve(s)&(1u<<BIT(3,WF)));memo.clear();}
void extended_tests(){St s;s.h=SB(R)|SB(L)|SB(Y);s.hp=1;s.lele=1;assert(solve(s)==65535);s.h=SB(R)|SB(X);s.lele=0;assert(bool(solve(s)&(1u<<WF))==oppBench);s.supporter=1;assert(!(solve(s)&(1u<<WF)));s={};s.h=SB(A);s.d=SB(R)|SB(S)|SB(X);s.hp=1;assert(solve(s)&(1u<<VF));assert(!(solve(s)&(1u<<WF)));s={};s.h=SB(T)|SB(R);s.d=SB(X);s.hp=1;assert(bool(solve(s)&(1u<<WF))==oppBench);memo.clear();}
// Practical actor-only query interface. Query first action with observed h only;
// branch may receive Prize composition ONLY after first-action inspection.
const array<string,N> CN={"V","VMAX","Lele","Latias","Radiant","Arven","Float","FSS","Heavy","Guzma","SkyField","Fog","Ball","Psychic","Other"};
const array<string,ACTS> AN={"direct","arven","lele","stone","fog","ball","heavy","ball-guzma","ball-sky"};
const array<string,4> GN={"VG","VF","WG","WF"};
Counts parse_counts(const string&arg,int total){Counts a{};size_t start=0;int sum=0;for(int c=0;c<N;++c){if(!extended&&(c==X||c==Y))continue;size_t end=arg.find(',',start);if((c==N-1)!=(end==string::npos))throw runtime_error(extended?"expected 15 comma-separated counts":"expected 13 comma-separated counts");string v=arg.substr(start,end==string::npos?end:end-start);size_t used=0;a[c]=stoi(v,&used);if(used!=v.size()||a[c]<0||a[c]>CAP[c])throw runtime_error("invalid count for "+CN[c]);sum+=a[c];start=end==string::npos?arg.size():end+1;}if(sum!=total)throw runtime_error("wrong count total");return a;}
template<class Names> int lookup(const string&arg,const Names&names){for(size_t i=0;i<names.size();++i)if(arg==names[i])return int(i);throw runtime_error("unknown value: "+arg);}
string describe(int a,const St&s,const St&q){string out=AN[a];vector<string> got;for(int c=T;c<=P;++c){bool took=false;if(c==G)took=q.dg<s.dg;else if(c==B)took=q.db<s.db;else if(c==P)took=q.dp<s.dp;else if(a==HEAVY)took=(s.pr&SB(c))&&!(q.pr&SB(c));else took=s.deck(c)&&!q.deck(c);if(took)got.push_back(CN[c]);}if(a==BALL||a==BALL_GUZMA||a==BALL_SKY){if(s.held(X)&&!q.held(X))out+=" [discard Guzma]";else if(s.held(Y)&&!q.held(Y))out+=" [discard Sky Field]";else out+=" [discard designated Other]";}if(!got.empty()){out+=" -> ";for(size_t i=0;i<got.size();++i){if(i)out+=" + ";out+=got[i];}}else out+=(a==STONE?" -> other (mandatory)":" -> decline");return out;}
struct Plan {bool valid=false;vector<string> steps;int spent=0,stone=0,lele=0;bool floatReady=false,latiasReady=false,guzmaReady=false,skyRequired=false;};
bool better(const Plan&a,const Plan&b){if(!a.valid)return false;if(!b.valid)return true;return make_tuple(a.stone,a.spent,a.lele,a.steps.size(),a.steps)<make_tuple(b.stone,b.spent,b.lele,b.steps.size(),b.steps);}
unordered_map<U,Plan> pmemo;
Plan continuation(const St&s,int bit){Mask need=Mask(1u<<bit);if(!(solve(s)&need))return {};if(goals(s)&need)return {true,{},s.spent,s.stone,s.lele,float_pivot(s),latias_pivot(s),guzma_pivot(s),s.lele&&s.held(L)&&!s.sky&&ctx.sky&&s.held(Y)};auto it=pmemo.find(s.key());if(it!=pmemo.end())return it->second;Plan best;for(int a:{FOG,HEAVY,ARVEN,LELE,BALL,STONE,BALL_GUZMA,BALL_SKY}){if(a==LELE&&(s.supporter||(!s.deck(A)&&!s.deck(X))))continue;successors(s,a,false,[&](const St&q){Plan p=continuation(q,bit);if(!p.valid)return;p.steps.insert(p.steps.begin(),describe(a,s,q));if(better(p,best))best=move(p);});}pmemo.emplace(s.key(),best);return best;}
Plan after_first(const St&s,int bit,int a){if(a==DIRECT)return (goals(s)&(1u<<bit))?Plan{true,{},s.spent,s.stone,s.lele,float_pivot(s),latias_pivot(s),guzma_pivot(s),s.lele&&s.held(L)&&!s.sky&&ctx.sky&&s.held(Y)}:Plan{};Plan best;successors(s,a,true,[&](const St&q){Plan p=continuation(q,bit);if(!p.valid)return;p.steps.insert(p.steps.begin(),describe(a,s,q));if(better(p,best))best=move(p);});return best;}
int query(int argc,char**argv){string mode=argv[1];try{if((mode=="--post"&&argc!=5)||(mode=="--branch"&&argc!=7))throw runtime_error("usage: --post H BUDGET GOAL | --branch H BUDGET GOAL ACTION PRIZES");Counts h=parse_counts(argv[2],7);if(!h[V])throw runtime_error("V must be in hand class");int b=stoi(argv[3]);if(b<0||b>3)throw runtime_error("budget 0..3");int goal=lookup(argv[4],GN),bit=BIT(b,goal);if(mode=="--post"){U worlds=0,grouped=0;Table a=posttable(h,worlds,grouped);U best=0;for(int act=0;act<ACTS;++act)best=max(best,a[act][bit]);cout<<"goal="<<GN[goal]<<" budget="<<b<<" denominator="<<CH[52][6]<<"; first search uses no prize input\n";for(int act=0;act<ACTS;++act)cout<<AN[act]<<" "<<a[act][bit]<<" / "<<CH[52][6]<<" "<<(100.L*a[act][bit]/CH[52][6])<<"%"<<(best&&a[act][bit]==best?" BEST":"")<<"\n";if(!best)cout<<"No successful restricted route\n";return 0;}
int a=lookup(argv[5],AN);Counts p=parse_counts(argv[6],6);for(int c=0;c<N;++c)if(h[c]+p[c]>CAP[c])throw runtime_error("hand+Prize exceeds inventory for "+CN[c]);int k=prize_key(h,p);if(!(k&(1<<14))){cout<<"No two-VMAX Gate: fewer than two VMAX in deck\n";return 0;}St s=make_state(h,k);Plan plan=after_first(s,bit,a);if(!plan.valid){cout<<"No continuation to stated goal after this first action in inspected allocation\n";return 0;}cout<<"First-action resolution and continuation (known allocation only):\n";if(goal>=WG)cout<<"Ensure V is Benched before any Star Alchemy.\n";for(auto&step:plan.steps)cout<<step<<"\n";if(goal>=WG){cout<<"Pivot: ";if(plan.floatReady)cout<<"attach Float to Wobbuffet";if(plan.floatReady&&plan.latiasReady)cout<<" OR ";if(plan.latiasReady)cout<<(plan.skyRequired?"play Sky Field, then bench Latias (Skyliner)":"bench Latias (Skyliner)");if(plan.floatReady||plan.latiasReady)cout<<"; retreat Wobbuffet to V";if(plan.guzmaReady)cout<<((plan.floatReady||plan.latiasReady)?" OR ":"")<<"play Guzma selecting opposing Bench target and own V";cout<<" before playing Radiant.\n";}if(goal==VF||goal==WF)cout<<"Manually attach Psychic to V.\n";cout<<"Play Radiant from hand; resolve Gate for two VMAX from deck.\n";cout<<"Star Alchemy spent="<<plan.stone<<" designated discards="<<plan.spent<<" Lele benched="<<plan.lele<<"\n";return 0;}catch(const exception&e){cerr<<e.what()<<"\n";return 2;}}

// Known-own-deck draw fallback: choose actions before random draw, then adapt to observed new hand.
// Input H,D,P are current exact zone counts, not opening counts. Use only after legal own-zone inspection.
// Category order = extended H columns plus Lillie,Iono (Other excludes both).
constexpr int LD=N,IO=N+1,DN=N+2;
using DC=array<int,DN>;
struct Bank{bool lele=false,latias=false,flt=false,fss=false,sky=false,psychic=false,stone=false;int spent=0;};
DC parse_draw_counts(const string&arg){DC a{};size_t start=0;for(int c=0;c<DN;++c){size_t end=arg.find(',',start);if((c==DN-1)!=(end==string::npos))throw runtime_error("expected 17 counts (extended H + Lillie,Iono)");string v=arg.substr(start,end==string::npos?end:end-start);size_t n=0;a[c]=stoi(v,&n);if(n!=v.size()||a[c]<0||a[c]>60)throw runtime_error("invalid draw count");start=end==string::npos?arg.size():end+1;}return a;}
Bank parse_bank(const string&arg){array<int,8> b{};size_t start=0;for(int i=0;i<8;++i){size_t end=arg.find(',',start);if((i==7)!=(end==string::npos))throw runtime_error("expected bank flags Lele,Latias,Float,FSS,Sky,Psychic,Stone,Spent");string v=arg.substr(start,end==string::npos?end:end-start);size_t n=0;b[i]=stoi(v,&n);if(n!=v.size()||b[i]<0||b[i]>(i==7?2:1))throw runtime_error("invalid bank flag");start=end==string::npos?arg.size():end+1;}return {bool(b[0]),bool(b[1]),bool(b[2]),bool(b[3]),bool(b[4]),bool(b[5]),bool(b[6]),b[7]};}
int dtotal(const DC&a){int r=0;for(int n:a)r+=n;return r;}
void enumerate_draw(const DC&caps,int n,const function<void(const DC&,U)>&cb){DC a{};array<int,DN+1> suffix{};for(int i=DN-1;i>=0;--i)suffix[i]=suffix[i+1]+caps[i];auto go=[&](auto&&self,int i,int left,U w)->void{if(i==DN){if(!left)cb(a,w);return;}for(int x=max(0,left-suffix[i+1]);x<=min(caps[i],left);++x){a[i]=x;self(self,i+1,left-x,w*CH[caps[i]][x]);}};go(go,0,n,1);}
St draw_state(const DC&h,const DC&d,const DC&p,const Bank&b,bool supportUsed){St s;for(int c=T;c<=Y;++c){if(h[c])s.h|=SB(c);if(d[c])s.d|=SB(c);}if(b.latias)s.h|=SB(L);if(b.flt)s.h|=SB(F);if(b.fss&&!b.stone)s.h|=SB(S);s.hg=h[G];s.hb=h[B];s.dg=min(2,d[G]);s.db=min(2,d[B]);s.hp=(h[P]>0)||b.psychic;s.dp=d[P]>0;for(int c:{T,L,R})if(p[c])s.pr|=SB(c);s.spent=b.spent;s.remain=min(2-b.spent,h[O]+h[LD]+h[IO]);s.stone=b.stone;s.lele=b.lele;s.supporter=supportUsed||!ctx.support;s.latiasBench=b.latias;s.sky=b.sky;return s;}
struct DrawOutcome{U num=0,den=1;int bankmask=0,card=0;U grouped=0;};
DrawOutcome eval_draw(const DC&held,const DC&deck,const DC&prizes,const Bank&before,int card,int mask,int bit){if(!ctx.support)return {};DC h=held,d=deck;Bank b=before;--h[card];auto bank=[&](int i,int c,bool&flag){if(!(mask&(1<<i)))return true;if(flag||!h[c])return false;--h[c];flag=true;return true;};if(!bank(0,F,b.flt)||!bank(1,L,b.latias)||!bank(2,S,b.fss)||!bank(3,Y,b.sky)||!bank(4,P,b.psychic))return {};if((mask&4)&&b.stone)return {};if((mask&1)&&bit%4<WG)return {};DC pool=d,bottom{};if(card==LD){for(int i=0;i<DN;++i)pool[i]+=h[i];}else bottom=h;int n=card==LD?8:6;if(dtotal(pool)<n)return {};DrawOutcome out{0,CH[dtotal(pool)][n],mask,card,0};U total=0;enumerate_draw(pool,n,[&](const DC&draw,U weight){++out.grouped;total+=weight;DC rem{};for(int c=0;c<DN;++c)rem[c]=pool[c]-draw[c]+bottom[c];if(rem[VM]<2)return;St s=draw_state(draw,rem,prizes,b,true);if(solve(s)&(1u<<bit))out.num+=weight;});assert(total==out.den);return out;}
string bank_name(int mask){string s;for(auto [i,n]:array<pair<int,const char*>,5>{{{0,"attach Float to Wob"},{1,"bench Latias"},{2,"attach FSS to V"},{3,"play Sky Field"},{4,"manual Psychic to V"}}})if(mask&(1<<i)){if(!s.empty())s+="; ";s+=n;}return s.empty()?"none":s;}
int draw_query(int argc,char**argv){try{if(!extended||argc!=8)throw runtime_error("usage: --extended bench|no-bench --draw-plan H D P BUDGET GOAL BANKFLAGS");DC h=parse_draw_counts(argv[2]),d=parse_draw_counts(argv[3]),p=parse_draw_counts(argv[4]);int budget=stoi(argv[5]),goal=lookup(argv[6],GN);if(budget<0||budget>3||dtotal(p)!=6||dtotal(d)<8||dtotal(h)+dtotal(d)+dtotal(p)>59)throw runtime_error("invalid first-turn own-zone counts or budget");Bank b=parse_bank(argv[7]);if(goal<WG&&b.flt)throw runtime_error("Float-bank flag requires W starter");DC cap{};for(int i=0;i<N;++i)cap[i]=CAP[i];cap[O]=19+(goal<WG);cap[V]=3;cap[LD]=2;cap[IO]=1;DC used{};used[T]=b.lele;used[L]=b.latias;used[F]=b.flt;used[S]=b.fss;used[Y]=b.sky;used[P]=b.psychic;for(int c=0;c<DN;++c)if(h[c]+d[c]+p[c]+used[c]>cap[c])throw runtime_error("zone counts exceed physical inventory");int bit=BIT(budget,goal);bool deterministic=d[VM]>=2&&(solve(draw_state(h,d,p,b,false))&(1u<<bit));cout<<"Known-zone deterministic route: "<<(deterministic?"YES":"NO")<<"\n";if(deterministic)cout<<"For this setup-only goal, keep a guaranteed deterministic route rather than gambling.\n";vector<DrawOutcome> out;for(int card:{LD,IO})if(h[card])for(int mask=0;mask<32;++mask){auto v=eval_draw(h,d,p,b,card,mask,bit);if(v.card)out.push_back(v);}sort(out.begin(),out.end(),[](const DrawOutcome&a,const DrawOutcome&b){U left=a.num*b.den,right=b.num*a.den;if(left!=right)return left>right;int ca=__builtin_popcount((unsigned)a.bankmask),cb=__builtin_popcount((unsigned)b.bankmask);return tie(ca,a.card,a.bankmask)<tie(cb,b.card,b.bankmask);});if(out.empty()){cout<<"No held draw supporter with modeled legal route.\n";return 0;}cout<<fixed<<setprecision(8);for(size_t i=0;i<out.size();++i){auto v=out[i];cout<<(i==0?"BEST ":"")<<(v.card==LD?"Lillie":"Iono")<<" bank: "<<bank_name(v.bankmask)<<" | "<<v.num<<"/"<<v.den<<" = "<<100.L*v.num/v.den<<"% | draw classes "<<v.grouped<<"\n";}cout<<"Only held draw supporters and pre-banking from held cards; no extra pre-draw searches, no opponent interference.\n";return 0;}catch(const exception&e){cerr<<e.what()<<"\n";return 2;}}

// Resolve an already-inspected arbitrary first-turn state, including banked resources after a draw Supporter.
int known_query(int argc,char**argv){try{bool branch=string(argv[1])=="--known-branch";if(!extended||argc!=(branch?10:9))throw runtime_error("usage: --extended bench|no-bench --known-plan H D P BUDGET GOAL BANKFLAGS SUPPORTUSED | --known-branch same + FIRSTACTION");DC h=parse_draw_counts(argv[2]),d=parse_draw_counts(argv[3]),p=parse_draw_counts(argv[4]);int budget=stoi(argv[5]),goal=lookup(argv[6],GN),support=stoi(argv[8]);if(budget<0||budget>3||support<0||support>1||dtotal(p)!=6||dtotal(h)+dtotal(d)+dtotal(p)>59)throw runtime_error("invalid first-turn own-zone counts or budget");Bank b=parse_bank(argv[7]);if(goal<WG&&b.flt)throw runtime_error("Float-bank flag requires W starter");DC cap{};for(int i=0;i<N;++i)cap[i]=CAP[i];cap[O]=19+(goal<WG);cap[V]=3;cap[LD]=2;cap[IO]=1;DC used{};used[T]=b.lele;used[L]=b.latias;used[F]=b.flt;used[S]=b.fss;used[Y]=b.sky;used[P]=b.psychic;for(int c=0;c<DN;++c)if(h[c]+d[c]+p[c]+used[c]>cap[c])throw runtime_error("zone counts exceed physical inventory");int bit=BIT(budget,goal);St st=draw_state(h,d,p,b,support);Plan plan;if(d[VM]>=2)plan=branch?after_first(st,bit,lookup(argv[9],AN)):continuation(st,bit);if(!plan.valid){cout<<"No known-zone continuation in restricted model\n";return 0;}cout<<"Known-zone continuation (no hidden order used):\n";for(auto&step:plan.steps){if(step.rfind("stone",0)==0&&!b.fss)cout<<"Attach Forest Seal Stone to V before Star Alchemy.\n";cout<<step<<"\n";}if(goal>=WG){if(b.latias&&plan.lele&&!b.sky)cout<<"Play Sky Field to fit both banked Latias and Lele before Gate.\n";cout<<"Pivot: ";if(plan.floatReady)cout<<(b.flt?"Float already attached to Wob":"attach Float to Wob");if(plan.floatReady&&plan.latiasReady)cout<<" OR ";if(plan.latiasReady)cout<<(b.latias?"Latias already Benched (Skyliner)":plan.skyRequired?"play Sky Field then bench Latias":"bench Latias (Skyliner)");if(plan.floatReady||plan.latiasReady)cout<<"; retreat Wobbuffet to V";if(plan.guzmaReady)cout<<((plan.floatReady||plan.latiasReady)?" OR ":"")<<"play Guzma selecting opposing Bench target and own V";cout<<" before Radiant.\n";}if((goal==VF||goal==WF)&&!b.psychic)cout<<"Manually attach Psychic to V.\n";cout<<"Play Radiant from hand and resolve Gate for two VMAX from deck.\n";return 0;}catch(const exception&e){cerr<<e.what()<<"\n";return 2;}}

// K0 -> post-refresh posterior: unknown pool U is the original unseen deck+six Prizes.
// RETURNED excludes the played Supporter and banked cards; DRAW is the observed 8/6 cards.
struct Posterior{U den=0,allocations=0;array<U,ACTS> num{};};
Posterior posterior(const DC&unknown,const DC&returned,const DC&draw,const Bank&b,int card,int bit){Posterior out;enumerate_draw(unknown,6,[&](const DC&p,U wp){U wd=1;DC d{};for(int c=0;c<DN;++c){int pool=unknown[c]-p[c]+(card==LD?returned[c]:0);if(draw[c]>pool)return;wd*=CH[pool][draw[c]];d[c]=unknown[c]-p[c]+returned[c]-draw[c];}U w=wp*wd;if(!w)return;++out.allocations;out.den+=w;if(d[VM]<2)return;St st=draw_state(draw,d,p,b,true);for(int a=0;a<ACTS;++a){if(a!=DIRECT&&!available(st,a))continue;if(firstmask(st,a)&(1u<<bit))out.num[a]+=w;}});return out;}
int posterior_query(int argc,char**argv){try{if(!extended||argc!=9)throw runtime_error("usage: --extended bench|no-bench --posterior-plan UNKNOWN RETURNED DRAW BUDGET GOAL BANKFLAGS lillie|iono");DC u=parse_draw_counts(argv[2]),r=parse_draw_counts(argv[3]),h=parse_draw_counts(argv[4]);int budget=stoi(argv[5]),goal=lookup(argv[6],GN);Bank b=parse_bank(argv[7]);string name=argv[8];int card=name=="lillie"?LD:name=="iono"?IO:-1;if(card<0||budget<0||budget>3||dtotal(h)!=(card==LD?8:6)||dtotal(u)<14||dtotal(u)+dtotal(r)>58)throw runtime_error("invalid K0 refresh input");DC cap{};for(int i=0;i<N;++i)cap[i]=CAP[i];cap[O]=19+(goal<WG);cap[V]=3;cap[LD]=2;cap[IO]=1;DC used{};used[T]=b.lele;used[L]=b.latias;used[F]=b.flt;used[S]=b.fss;used[Y]=b.sky;used[P]=b.psychic;++used[card];for(int c=0;c<DN;++c)if(u[c]+r[c]+used[c]>cap[c])throw runtime_error("K0 inventory exceeds physical cap");auto p=posterior(u,r,h,b,card,BIT(budget,goal));if(!p.den)throw runtime_error("observed draw impossible under this prior");U best=0;for(U n:p.num)best=max(best,n);cout<<"Posterior allocations="<<p.allocations<<" weight="<<p.den<<"; first action sees observed draw only, not Prize identities\n";cout<<fixed<<setprecision(8);for(int a=0;a<ACTS;++a)cout<<AN[a]<<" "<<p.num[a]<<"/"<<p.den<<" = "<<100.L*p.num[a]/p.den<<"%"<<(best&&p.num[a]==best?" BEST":"")<<"\n";if(!best)cout<<"No successful restricted route\n";return 0;}catch(const exception&e){cerr<<e.what()<<"\n";return 2;}}

// Monte Carlo outer expectation over new observable hands; inner posterior/action choice is exact.
// Paired seeds reuse the same unknown-pool shuffle for all options; no actual Prize assignment enters policy.
struct MCArm{int card=0,mask=0;size_t distinct=0;long double mean=0,se=0;vector<long double> values;};
Posterior prior_no_draw(const DC&u,const DC&h,const Bank&b,int bit){Posterior out;enumerate_draw(u,6,[&](const DC&p,U w){DC d{};for(int c=0;c<DN;++c)d[c]=u[c]-p[c];++out.allocations;out.den+=w;if(d[VM]<2)return;St st=draw_state(h,d,p,b,false);for(int a=0;a<ACTS;++a){if(a!=DIRECT&&!available(st,a))continue;if(firstmask(st,a)&(1u<<bit))out.num[a]+=w;}});assert(out.den==CH[dtotal(u)][6]);return out;}
vector<int> physical(const DC&a){vector<int> v;for(int c=0;c<DN;++c)for(int j=0;j<a[c];++j)v.push_back(c);return v;}
U draw_key(const DC&h){U key=0;for(int x:h)key=key*12+x;return key;}
pair<long double,long double> mean_se(const vector<long double>&x){long double m=0,s=0;size_t n=0;for(auto v:x){++n;long double d=v-m;m+=d/n;s+=d*(v-m);}return {m,n>1?sqrtl(max(0.L,s/(n-1)/n)):0};}
MCArm sample_arm(const DC&u,const DC&held,const Bank&before,int card,int mask,int bit,int n,U seed){if(!ctx.support)return {};DC h=held;Bank b=before;--h[card];auto bank=[&](int i,int c,bool&flag){if(!(mask&(1<<i)))return true;if(flag||!h[c])return false;--h[c];flag=true;return true;};if(!bank(0,F,b.flt)||!bank(1,L,b.latias)||!bank(2,S,b.fss)||!bank(3,Y,b.sky)||!bank(4,P,b.psychic))return {};if((mask&4)&&b.stone)return {};if((mask&1)&&bit%4<WG)return {};auto base=physical(u),returned=physical(h);int count=card==LD?8:6;MCArm out;out.card=card;out.mask=mask;out.values.reserve(n);unordered_map<U,long double> cache;for(int i=0;i<n;++i){mt19937_64 rng(seed+U(i)*0x9e3779b97f4a7c15ULL);auto unknown=base;shuffle(unknown.begin(),unknown.end(),rng);vector<int> deck(unknown.begin()+6,unknown.end());if(card==LD){deck.insert(deck.end(),returned.begin(),returned.end());shuffle(deck.begin(),deck.end(),rng);}if((int)deck.size()<count)return {};DC draw{};for(int j=0;j<count;++j)++draw[deck[j]];U k=draw_key(draw);auto it=cache.find(k);long double value;if(it!=cache.end())value=it->second;else{auto p=posterior(u,h,draw,b,card,bit);assert(p.den);U best=0;for(U z:p.num)best=max(best,z);value=(long double)best/p.den;cache.emplace(k,value);}out.values.push_back(value);if(memo.size()>20000000)memo.clear();}out.distinct=cache.size();tie(out.mean,out.se)=mean_se(out.values);return out;}
int k0_draw_query(int argc,char**argv){try{if(!extended||argc!=9)throw runtime_error("usage: --extended bench|no-bench --k0-draw H UNKNOWN BUDGET GOAL BANKFLAGS SAMPLES SEED");DC h=parse_draw_counts(argv[2]),u=parse_draw_counts(argv[3]);int budget=stoi(argv[4]),goal=lookup(argv[5],GN),n=stoi(argv[7]);Bank b=parse_bank(argv[6]);U seed=stoull(argv[8]);if(budget<0||budget>3||n<2||n>4096||dtotal(u)<14||dtotal(u)+dtotal(h)>59)throw runtime_error("invalid K0 draw input");DC cap{};for(int i=0;i<N;++i)cap[i]=CAP[i];cap[O]=19+(goal<WG);cap[V]=3;cap[LD]=2;cap[IO]=1;DC used{};used[T]=b.lele;used[L]=b.latias;used[F]=b.flt;used[S]=b.fss;used[Y]=b.sky;used[P]=b.psychic;for(int c=0;c<DN;++c)if(u[c]+h[c]+used[c]>cap[c])throw runtime_error("K0 inventory exceeds physical cap");int bit=BIT(budget,goal);auto no=prior_no_draw(u,h,b,bit);U best=0;for(U z:no.num)best=max(best,z);cout<<fixed<<setprecision(6)<<"Exact no-draw restricted route: "<<best<<"/"<<no.den<<" = "<<100.L*best/no.den<<"%\n";for(int a=0;a<ACTS;++a)if(best&&no.num[a]==best)cout<<"  "<<AN[a]<<" BEST\n";vector<MCArm> arms;for(int card:{LD,IO})if(h[card])for(int mask=0;mask<32;++mask){auto arm=sample_arm(u,h,b,card,mask,bit,n,seed);if(arm.card){cerr<<"arm "<<(card==LD?"Lillie":"Iono")<<" "<<bank_name(mask)<<" n="<<n<<" mean="<<100.L*arm.mean<<"%\n";arms.push_back(move(arm));}}sort(arms.begin(),arms.end(),[](const MCArm&a,const MCArm&b){return a.mean>b.mean;});cout<<"Monte Carlo outer samples per arm="<<n<<" seed="<<seed<<"; exact conditional best first action for each observed draw.\n";for(size_t i=0;i<arms.size();++i){auto&a=arms[i];vector<long double> diff(n);for(int j=0;j<n;++j)diff[j]=arms[0].values[j]-a.values[j];auto [dm,ds]=mean_se(diff);cout<<(i==0?"BEST SAMPLE ARM ":"")<<(a.card==LD?"Lillie":"Iono")<<" bank: "<<bank_name(a.mask)<<" | "<<100.L*a.mean<<"% MC SE "<<100.L*a.se<<" pp | paired gap from top "<<100.L*dm<<" +/- "<<100.L*ds<<" pp SE | distinct "<<a.distinct<<"\n";}cout<<"Development estimate, not exact outer probability, not a full optimal K0 policy: excludes pre-draw tutors and search-then-draw fallback. Confirm close decisions on independent samples.\n";return 0;}catch(const exception&e){cerr<<e.what()<<"\n";return 2;}}

// One fixed, legal information-revealing search, then adaptive target selection and
// deterministic continuation or immediate draw refresh. Outer sampling only over Prize allocations;
// conditional continuation is exact and sees Prizes only after the committed search.
struct PreSearchChoice{long double prob=0;int target=-1,card=0,mask=0;};
PreSearchChoice presearch_value(const DC&held,const DC&deck,const DC&prizes,const Bank&before,int action,int bit){
 PreSearchChoice best;if(!ctx.item)return best; DC base=held;int source=action==FOG?G:H;if(!base[source])return best;--base[source];
 vector<int> targets{-1};if(action==FOG){for(int c:{T,L,P})if(deck[c])targets.push_back(c);}else{for(int c:{T,L,R})if(prizes[c])targets.push_back(c);}
 for(int target:targets){DC h=base,d=deck,p=prizes;Bank b=before;if(target>=0){++h[target];if(action==FOG)--d[target];else{--p[target];++p[H];}}
   if(d[VM]>=2&&(solve(draw_state(h,d,p,b,false))&(1u<<bit)))return {1.L,target,0,0};
   for(int card:{LD,IO})if(h[card])for(int mask=0;mask<32;++mask){auto v=eval_draw(h,d,p,b,card,mask,bit);if(!v.card)continue;long double x=(long double)v.num/v.den;if(x>best.prob)best={x,target,card,mask};}
 }return best;
}
int presearch_query(int argc,char**argv){try{
 if(!extended||argc!=10)throw runtime_error("usage: --extended bench|no-bench --presearch-draw H UNKNOWN BUDGET GOAL BANKFLAGS SAMPLES SEED fog|heavy");
 DC h=parse_draw_counts(argv[2]),u=parse_draw_counts(argv[3]);int budget=stoi(argv[4]),goal=lookup(argv[5],GN),n=stoi(argv[7]);Bank b=parse_bank(argv[6]);U seed=stoull(argv[8]);string name=argv[9];int action=name=="fog"?FOG:name=="heavy"?HEAVY:-1;
 if(!ctx.item||action<0||budget<0||budget>3||n<2||n>512||dtotal(u)<14||dtotal(u)+dtotal(h)>59||!h[action==FOG?G:H])throw runtime_error("invalid held search or K0 input");
 DC cap{};for(int i=0;i<N;++i)cap[i]=CAP[i];cap[O]=19+(goal<WG);cap[V]=3;cap[LD]=2;cap[IO]=1;DC used{};used[T]=b.lele;used[L]=b.latias;used[F]=b.flt;used[S]=b.fss;used[Y]=b.sky;used[P]=b.psychic;for(int c=0;c<DN;++c)if(u[c]+h[c]+used[c]>cap[c])throw runtime_error("K0 inventory exceeds physical cap");
 int bit=BIT(budget,goal);auto pool=physical(u);vector<long double> vals;unordered_map<U,PreSearchChoice> cache;array<int,DN+1> targetcounts{};int deterministic=0;for(int i=0;i<n;++i){mt19937_64 rng(seed+U(i)*0x9e3779b97f4a7c15ULL);auto a=pool;shuffle(a.begin(),a.end(),rng);DC p{},d=u;for(int j=0;j<6;++j){++p[a[j]];--d[a[j]];}U key=draw_key(p);auto it=cache.find(key);PreSearchChoice v;if(it!=cache.end())v=it->second;else{v=presearch_value(h,d,p,b,action,bit);cache.emplace(key,v);}vals.push_back(v.prob);++targetcounts[v.target+1];deterministic+=(v.prob==1.L&&v.card==0);if(memo.size()>20000000)memo.clear();if((i+1)%16==0)cerr<<"presearch samples="<<i+1<<" distinct="<<cache.size()<<"\n";}
 auto [mean,se]=mean_se(vals);cout<<fixed<<setprecision(6)<<"Fixed first "<<name<<", then choose search target and best deterministic/refresh plan after lawful inspection.\n"<<"Funded/selected goal estimate="<<100.L*mean<<"% MC SE="<<100.L*se<<" pp; samples="<<n<<" seed="<<seed<<" distinct prize groups="<<cache.size()<<" deterministic successes="<<deterministic<<"\n";for(int c=-1;c<DN;++c)if(targetcounts[c+1])cout<<"target="<<c<<" count="<<targetcounts[c+1]<<"\n";cout<<"One fixed pre-search only; no other pre-draw tutors; exact post-inspection draw enumeration; sampled Prize composition only visible after search. Not a game policy.\n";return 0;
 }catch(const exception&e){cerr<<e.what()<<"\n";return 2;}}

// Invoke only while the chosen search is resolving and own zones are legitimately known.
int presearch_known_query(int argc,char**argv){try{
 if(!extended||argc!=9)throw runtime_error("usage: --extended bench|no-bench --presearch-known H D P BUDGET GOAL BANKFLAGS fog|heavy");
 DC h=parse_draw_counts(argv[2]),d=parse_draw_counts(argv[3]),p=parse_draw_counts(argv[4]);int budget=stoi(argv[5]),goal=lookup(argv[6],GN);Bank b=parse_bank(argv[7]);string name=argv[8];int action=name=="fog"?FOG:name=="heavy"?HEAVY:-1;
 if(!ctx.item||action<0||budget<0||budget>3||dtotal(p)!=6||dtotal(h)+dtotal(d)+dtotal(p)>59||!h[action==FOG?G:H])throw runtime_error("invalid search-resolution state");
 DC cap{};for(int i=0;i<N;++i)cap[i]=CAP[i];cap[O]=19+(goal<WG);cap[V]=3;cap[LD]=2;cap[IO]=1;DC used{};used[T]=b.lele;used[L]=b.latias;used[F]=b.flt;used[S]=b.fss;used[Y]=b.sky;used[P]=b.psychic;for(int c=0;c<DN;++c)if(h[c]+d[c]+p[c]+used[c]>cap[c])throw runtime_error("zone counts exceed physical cap");
 auto v=presearch_value(h,d,p,b,action,BIT(budget,goal));cout<<fixed<<setprecision(8)<<"Resolve committed "<<name<<": "<<(v.target<0?"decline":CN[v.target])<<"; conditional goal probability="<<100.L*v.prob<<"%\n";if(v.card)cout<<"Bank: "<<bank_name(v.mask)<<"; play "<<(v.card==LD?"Lillie":"Iono")<<"; use --known-plan after observing draw.\n";else if(v.prob==1.L)cout<<"Use --known-plan after resolving this search; deterministic route exists.\n";else cout<<"No positive route in restricted model.\n";return 0;
 }catch(const exception&e){cerr<<e.what()<<"\n";return 2;}}

void context_tests(){auto saved=ctx;bool ob=oppBench;ctx={};oppBench=true;St s;s.h=SB(A)|SB(F);s.d=SB(S)|SB(R);s.hp=1;s.db=1;s.remain=1;ctx.item=false;memo.clear();assert(solve(s)&(1u<<WF));ctx.stone=false;memo.clear();assert(!(solve(s)&(1u<<WF)));ctx={};ctx.support=false;memo.clear();assert(!(solve(s)&(1u<<WF)));s={};s.h=SB(R)|SB(F)|SB(X);s.hp=1;ctx={};ctx.gateRetreat=false;memo.clear();assert(solve(s)&(1u<<WF));assert(!float_pivot(s)&&guzma_pivot(s));ctx.gateGuzma=false;memo.clear();assert(!(solve(s)&(1u<<WF)));ctx.gateV=false;memo.clear();assert(!solve(s));ctx=saved;oppBench=ob;memo.clear();}
struct Aggregate{U hands=0,physical=0,parity=0,positiveParity=0,fundedParity=0,allParity=0,none=0;array<long double,16> vals{};long double chosenW=0;};
int main(int argc,char**argv){if(argc>2&&string(argv[1])=="--extended"){extended=true;string mode=argv[2];if(mode!="bench"&&mode!="no-bench"){cerr<<"--extended bench|no-bench\n";return 2;}oppBench=mode=="bench";CAP[X]=CAP[Y]=1;CAP[O]=22;argv+=2;argc-=2;}if(argc>2&&string(argv[1])=="--context"){try{ctx=parse_context(argv[2]);}catch(const exception&e){cerr<<e.what()<<"\n";return 2;}argv+=2;argc-=2;}bool csv=false;int limit=0;for(int i=1;i<argc;++i){string v=argv[i];if(v=="--csv")csv=true;else if(v=="--limit"&&i+1<argc)limit=stoi(argv[++i]);}for(int n=0;n<=60;++n){CH[n][0]=1;for(int k=1;k<=n;++k)CH[n][k]=(n?CH[n-1][k-1]+CH[n-1][k]:0);}int total=0;for(int c:CAP)total+=c;assert(total==59);bool savedOpp=oppBench;PublicContext savedCtx=ctx;ctx={};oppBench=false;tests();oppBench=savedOpp;if(extended)extended_tests();context_tests();ctx=savedCtx;memo.clear();if(argc>1&&string(argv[1])=="--draw-plan")return draw_query(argc,argv);if(argc>1&&(string(argv[1])=="--known-plan"||string(argv[1])=="--known-branch"))return known_query(argc,argv);if(argc>1&&string(argv[1])=="--posterior-plan")return posterior_query(argc,argv);if(argc>1&&string(argv[1])=="--k0-draw")return k0_draw_query(argc,argv);if(argc>1&&string(argv[1])=="--presearch-draw")return presearch_query(argc,argv);if(argc>1&&string(argv[1])=="--presearch-known")return presearch_known_query(argc,argv);if(argc>1&&(string(argv[1])=="--post"||string(argv[1])=="--branch"))return query(argc,argv);if(!ctx.gateV){cerr<<"Aggregate mode requires direct V Gate eligibility; query actual restricted state instead.\n";return 2;}unordered_map<U,Vec> data;U worlds=0,grouped=0;int n=0;enumerate(CAP,7,[&](const Counts&h,U){if(!h[V]||(limit&&n>=limit))return;++n;data.emplace(handkey(h),post(h,worlds,grouped));if(memo.size()>20000000)memo.clear();if(n%500==0)cerr<<"post="<<n<<" groups="<<grouped<<" memo="<<memo.size()<<"\n";});if(limit){cerr<<"LIMIT post="<<n<<" grouped="<<grouped<<" worlds="<<worlds<<"\n";return 0;}
 U D=53*CH[52][6];array<Aggregate,4> agg{};array<U,5> gaps{};if(csv){cout<<"V,VM,Lele,Latias,Radiant,Arven,Float,FSS,Heavy";if(extended)cout<<",Guzma,SkyField";cout<<",Fog,Ball,Psychic,Other,weight";for(int b=0;b<4;++b)for(auto goal:{"VG","VF","WG","WF"})cout<<",b"<<b<<"_"<<goal;cout<<"\n";}
 enumerate(CAP,6,[&](const Counts&h,U w){if(!h[V])return;Vec x{};for(int c=0;c<N;++c)if(h[c]<CAP[c]){Counts p=h;++p[c];const Vec&v=data.at(handkey(p));for(int i=0;i<16;++i)x[i]+=U(CAP[c]-h[c])*v[i];}bool parity=true,any=x[BIT(0,VG)]>0;for(int b=0;b<4;++b)parity&=x[BIT(b,VG)]==x[BIT(b,WG)]&&x[BIT(b,VF)]==x[BIT(b,WF)];bool fp=x[BIT(0,VF)]==x[BIT(0,WF)];int group=h[F]?1:h[L]?2:3;for(int i:{0,group}){auto &z=agg[i];++z.hands;z.physical+=w;z.parity+=w*(x[BIT(0,VG)]==x[BIT(0,WG)]);z.fundedParity+=w*fp;z.allParity+=w*parity;z.positiveParity+=w*(parity&&any);z.none+=w*!any;for(int b=0;b<16;++b)z.vals[b]+=(long double)w*x[b];z.chosenW+=(long double)w*(parity&&any);}
 U gap=x[BIT(0,VF)]-x[BIT(0,WF)];int gi=gap==0?0:gap*20<=D?1:gap*10<=D?2:gap*4<=D?3:4;gaps[gi]+=w;if(csv){for(int c=0;c<N;++c){if(!extended&&(c==X||c==Y))continue;cout<<h[c]<<',';}cout<<w;for(U z:x)cout<<','<<z;cout<<'\n';}});
 assert(agg[0].physical==CH[59][6]-CH[55][6]);U legal=CH[60][7]-CH[46][7];cerr<<fixed<<setprecision(8);cerr<<"post="<<n<<" worlds="<<worlds<<" grouped="<<grouped<<" denominator="<<D<<" original_physical="<<agg[0].physical<<" legal_openings="<<legal<<" both_W_V_legal_pct="<<(100.L*agg[0].physical/legal)<<"\n";
 for(int i=0;i<4;++i){auto &z=agg[i];cerr<<"GROUP "<<i<<" hands="<<z.hands<<" weight="<<z.physical<<" share_pct="<<100.L*z.physical/agg[0].physical<<" gate_parity_pct="<<100.L*z.parity/z.physical<<" funded_parity_pct="<<100.L*z.fundedParity/z.physical<<" all_budget_parity_pct="<<100.L*z.allParity/z.physical<<" positive_all_parity_pct="<<100.L*z.positiveParity/z.physical<<" no_gate_pct="<<100.L*z.none/z.physical<<"\n";for(int b=0;b<4;++b){cerr<<" budget "<<b;for(int g=0;g<4;++g)cerr<<" "<<100.L*z.vals[BIT(b,g)]/((long double)z.physical*D);cerr<<"\n";}}
 cerr<<"GAP bins <=0,<=5%,<=10%,<=25%,>25%:";for(U z:gaps)cerr<<' '<<100.L*z/agg[0].physical;cerr<<"\n";
}
